const markPaymentRefunded = `-- name: MarkPaymentRefunded :one
WITH refunded_payment AS (
    UPDATE payments AS payment
    SET
        status = 'refunded',
        failure_code = NULL,
        failure_message = NULL,
        refunded_at = now(),
        refund_available_at = NULL,
        refund_locked_at = NULL,
        updated_at = now()
    WHERE payment.id = $1
      AND payment.status = 'refund_pending'
      AND payment.refund_locked_at = $2
    RETURNING
        payment.id,
        payment.booking_id,
        payment.provider,
        payment.provider_payment_id,
        payment.provider_idempotency_key,
        payment.amount_minor,
        payment.currency,
        payment.status,
        payment.failure_code,
        payment.failure_message,
        payment.paid_at,
        payment.refunded_at,
        payment.created_at,
        payment.updated_at,
        payment.refund_attempts,
        payment.refund_available_at,
        payment.refund_locked_at
),
enqueued_email AS (
    INSERT INTO email_outbox (
        booking_id,
        event_type,
        recipient_email,
        payload
    )
    SELECT
        b.id,
        'payment_refunded',
        u.email,
        jsonb_build_object(
            'booking_id', b.id,
            'guest_name', u.full_name,
            'hotel_name', h.name,
            'room_type_name', rt.name,
            'check_in', b.check_in,
            'check_out', b.check_out,
            'rooms_count', b.rooms_count,
            'guest_count', b.guest_count,
            'price_per_night', b.price_per_night::text,
            'total_price', b.total_price::text,
            'currency', b.currency
        )
    FROM refunded_payment AS p
    JOIN bookings AS b
        ON b.id = p.booking_id
    JOIN users AS u
        ON u.id = b.user_id
    JOIN room_types AS rt
        ON rt.id = b.room_type_id
    JOIN hotels AS h
        ON h.id = rt.hotel_id
    ON CONFLICT (booking_id, event_type) DO NOTHING
    RETURNING booking_id
)
SELECT
    p.id,
    p.booking_id,
    p.provider,
    p.provider_payment_id,
    p.provider_idempotency_key,
    p.amount_minor,
    p.currency,
    p.status,
    p.failure_code,
    p.failure_message,
    p.paid_at,
    p.refunded_at,
    p.created_at,
    p.updated_at,
    p.refund_attempts,
    p.refund_available_at,
    p.refund_locked_at
FROM refunded_payment AS p
LEFT JOIN enqueued_email AS e
    ON e.booking_id = p.booking_id
`

